#include <iostream>
#include <unordered_map>

int main() {
    std::unordered_map<long long, int> first;
    long long x;
    int position = 0;
    while (std::cin >> x) {
        position++;
        auto it = first.find(x);
        if (it != first.end()) {
            std::cout << "значение " << x << ", позиции " << it->second << ' ' << position << '\n';
            return 0;
        }
        first[x] = position;
    }
    std::cout << "повторов нет\n";
    return 0;
}

