#include <iostream>
#include <unordered_map>

int main() {
    int n;
    long long k;
    if (!(std::cin >> n >> k) || n < 1) {
        return 0;
    }
    std::unordered_map<long long, long long> count;
    count.reserve(static_cast<std::size_t>(n) + 1);
    count[0] = 1;
    long long prefix = 0, answer = 0;
    for (int j = 0; j < n; j++) {
        long long x;
        std::cin >> x;
        prefix += x;
        auto it = count.find(prefix - k);
        if (it != count.end()) {
            answer += it->second;
        }
        ++count[prefix];
    }
    std::cout << answer << '\n';
    return 0;
}

